/**
 * The Lacey Ledger — a map of where everyone is.
 *
 * A drop-in component. Nothing is fetched at render time: the state outlines
 * below were projected once from the US Census cartographic boundary files
 * (public domain, via us-atlas) into an Albers equal-area projection with the
 * usual Alaska and Hawaii insets, and baked in as plain SVG paths.
 *
 * That matters for a private page. A tile-server map would hand the household's
 * locations to a third party on every page view; this one never leaves the box,
 * needs no API key, and works offline.
 *
 * Usage — one line in people.php or index.php, above the list of cards:
 *
 *     require_once __DIR__ . '/map.php';
 *     echo ledger_map($people);       // rows with a name + a place string
 *
 * Each row may be an array or an object with:
 *   name / who / label   what to call the pin
 *   place / location / where   "Mount Pleasant, SC" — looked up in the gazetteer
 *   lat + lon            used directly when present, skipping the lookup
 *   status               confirmed | inferred | stale  (styles the pin)
 *   href                 makes the pin a link, e.g. "person.php?id=13"
 */

declare(strict_types=1);

/**
 * Places the Ledger actually refers to, plus the larger US metros, so a row
 * that says "Houston, TX" lands in the right spot without a geocoding service.
 *
 * A place that is not in here is NOT guessed at — it is reported back as
 * unplaced, so the map never invents a location for someone.
 */
