/**
 * Project lon/lat to the baked 960x600 canvas. Returns null for anywhere the
 * projection does not cover, so an off-map person is listed, never misplaced.
 */
function ledger_project(float $lat, float $lon): ?array
{
    // [lon0, lat0, parallel1, parallel2, scale, tx, ty] — must match bake step.
    if ($lat > 50.0 && $lon < -128.0) {
        $p = [-152.0, 60.0, 55.0, 65.0, 360.0, 130.0, 540.0];
    } elseif ($lat > 15.0 && $lat < 24.0 && $lon > -162.0 && $lon < -152.0) {
        $p = [-157.0, 20.0, 8.0, 18.0, 820.0, 310.0, 560.0];
    } elseif ($lon > -130.0 && $lon < -66.0 && $lat > 22.0 && $lat < 51.0) {
        $p = [-96.0, 37.5, 29.5, 45.5, 1180.0, 480.0, 340.0];
    } else {
        return null;
    }

    [$lon0, $lat0, $par1, $par2, $scale, $tx, $ty] = $p;

    $p1 = deg2rad($par1);
    $p2 = deg2rad($par2);
    $n  = 0.5 * (sin($p1) + sin($p2));
    if (abs($n) < 1e-12) {
        return null;
    }
    $C    = cos($p1) ** 2 + 2 * $n * sin($p1);
    $rho0 = sqrt($C - 2 * $n * sin(deg2rad($lat0))) / $n;

    $rho = sqrt($C - 2 * $n * sin(deg2rad($lat))) / $n;
    $th  = $n * deg2rad($lon - $lon0);

    return [
        $scale * $rho * sin($th) + $tx,
        $ty - $scale * ($rho0 - $rho * cos($th)),
    ];
}

/** Look a place string up in the gazetteer. */
function ledger_locate(?string $place): ?array
{
    $key = strtolower(trim((string) $place));
    if ($key === '' || str_contains($key, 'unknown')) {
        return null;
    }
    $key = preg_replace('/\s+/', ' ', $key);
    return LEDGER_GAZETTEER[$key] ?? null;
}

/** Read a field from a row that may be an array or an object. */
function ledger_field(array|object $row, array $names): ?string
{
    foreach ($names as $n) {
        $v = is_array($row) ? ($row[$n] ?? null) : ($row->$n ?? null);
        if ($v !== null && trim((string) $v) !== '') {
            return (string) $v;
        }
    }
    return null;
}

/**
 * Render the map.
 *
 * @param iterable $rows people (or anything with a place)
 */
function ledger_map(iterable $rows, string $caption = ''): string
{
    $pins = [];      // keyed by rounded position, so a shared city is one pin
    $unplaced = [];

    foreach ($rows as $row) {
        $name = ledger_field($row, ['name', 'who', 'label', 'full_name']) ?? 'Someone';
        $lat  = ledger_field($row, ['lat', 'latitude']);
        $lon  = ledger_field($row, ['lon', 'lng', 'longitude']);
        $place = ledger_field($row, ['place', 'location', 'where', 'city']);

        $coords = ($lat !== null && $lon !== null)
            ? [(float) $lat, (float) $lon]
            : ledger_locate($place);

        if ($coords === null) {
            $unplaced[] = $name;
            continue;
        }

        $xy = ledger_project($coords[0], $coords[1]);
        if ($xy === null) {
            $unplaced[] = $name;
            continue;
        }

        // Snap to a grid a little wider than a pin, so two towns a few miles
        // apart (Mount Pleasant and Charleston, say) become one pin with a
        // count rather than two dots stacked on top of each other.
        $cell = 15.0;
        $key  = ((int) round($xy[0] / $cell)) . ':' . ((int) round($xy[1] / $cell));

        if (!isset($pins[$key])) {
            $pins[$key] = [
                'xs' => [], 'ys' => [],
                'places' => [],
                'names' => [],
                'status' => ledger_field($row, ['status']) ?? 'confirmed',
                'href' => ledger_field($row, ['href']),
            ];
        }
        $pins[$key]['xs'][] = $xy[0];
        $pins[$key]['ys'][] = $xy[1];
        $pins[$key]['names'][] = $name;
        if ($place !== null && !in_array($place, $pins[$key]['places'], true)) {
            $pins[$key]['places'][] = $place;
        }
        // A cluster is only as certain as its least certain member.
        if (($pins[$key]['status'] ?? '') === 'confirmed'
            && ($st = ledger_field($row, ['status'])) !== null && $st !== 'confirmed') {
            $pins[$key]['status'] = $st;
        }
    }

    $svg = '<svg class="usmap" viewBox="0 0 960 600" role="img" '
         . 'aria-label="Where everyone is">'
         . '<g class="usmap-land">' . LEDGER_US_PATHS . '</g>';

    // Pins last so they sit above every state outline.
    foreach ($pins as $pin) {
        $n  = count($pin['names']);
        $px = array_sum($pin['xs']) / $n;
        $py = array_sum($pin['ys']) / $n;
        $title = implode(', ', $pin['names'])
               . ($pin['places'] ? ' — ' . implode(' / ', $pin['places']) : '');
        $cls = 'pin pin-' . preg_replace('/[^a-z]/', '', strtolower($pin['status']));

        $mark = sprintf(
            '<g class="%s" transform="translate(%.1f %.1f)">'
            . '<circle class="pin-halo" r="13"/>'
            . '<circle class="pin-dot" r="5.5"/>'
            . ($n > 1 ? '<text class="pin-count" y="3.2">' . $n . '</text>' : '')
            . '<title>%s</title></g>',
            $cls, $px, $py, htmlspecialchars($title)
        );

        $svg .= $pin['href'] !== null
            ? '<a href="' . htmlspecialchars($pin['href']) . '">' . $mark . '</a>'
            : $mark;
    }

    $svg .= '</svg>';

    $out = '<div class="card map-card">' . $svg;
    if ($caption !== '') {
        $out .= '<p class="where chart-note">' . htmlspecialchars($caption) . '</p>';
    }
    if ($unplaced) {
        $out .= '<p class="where chart-note">Not on the map: '
              . htmlspecialchars(implode(', ', $unplaced)) . '.</p>';
    }
    return $out . '</div>';
}

/* When opened directly, show the component working against the places the
   Ledger actually refers to. Handy for checking a deploy. */
if (isset($_SERVER['SCRIPT_FILENAME'])
    && realpath($_SERVER['SCRIPT_FILENAME']) === realpath(__FILE__)) {
    $PAGE_TITLE = 'Map';
    require __DIR__ . '/header.php';
    echo '<h1>Map</h1><p class="kicker">A self-test of the map component.</p>';
    echo ledger_map([
        ['name' => 'Chris Lacey', 'place' => 'Mount Pleasant, SC', 'status' => 'confirmed'],
        ['name' => 'Addy Lacey',  'place' => 'Charleston, SC',     'status' => 'confirmed'],
        ['name' => 'John Mooney', 'place' => 'Mount Pleasant, SC', 'status' => 'confirmed'],
        ['name' => 'J. Nick Koston', 'place' => 'Houston, TX',     'status' => 'confirmed'],
        ['name' => 'David Farris',   'place' => 'Houston, TX',     'status' => 'confirmed'],
        ['name' => 'Kahana',      'place' => 'Mount Pleasant, SC', 'status' => 'inferred'],
        ['name' => 'Someone abroad', 'place' => 'Location unknown', 'status' => 'stale'],
    ], 'A pin per place; a number means more than one person there.');
    require __DIR__ . '/footer.php';
}
